        in.nextToken();
        int n1 = (int) in.nval;
        int[] a = new int[n1];
        for (int i = 0; i < n1; i++) {
            in.nextToken();
            a[i] = (int) in.nval;
        }
        in.nextToken();
        int n2 = (int) in.nval;
        int[] b = new int[n2];
        for (int i = 0; i < n2; i++) {
            in.nextToken();
            b[i] = (int) in.nval;
        }
        int[] res = subtract(a, b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
